function ActionDarkDreamCommonTeamNodeCell:UpdateTeamInfo(teamInfo)
    if IsNull(teamInfo) then return end
    self.teamInfo = teamInfo
    local cardsInfo = teamInfo.cardsInfo
    local data = {}
    for i, v in pairs(cardsInfo) do
        if not isNull(v) then
            local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
            local cardDojo = cardComponent:GetCardById(v.refId)
            if not isNull(cardDojo) then
                local tempDojo = clone(cardDojo)
                tempDojo.fettersCardId = v.fettersCardId
                tempDojo.fettersId = v.fettersId
                table.insert(data,tempDojo)
            end
        else
            table.insert(data,{})
        end
    end
    self.LB_MembersNode.Env:Refresh(data, false, 0.5, nil, nil, nil, true,0, true, true)

    -- 设置队伍战力
    self.Txt_CombatValue.text = tostring(teamInfo.combatValue)
end

function ActionDarkDreamCommonTeamNodeCell:SetParameters(index)
    self.cellIndex = index
end

return ActionDarkDreamCommonTeamNodeCell